from ecs_models import ClusterState, ContainerInstance, DrainDecision, InstanceEvent, PlacementRequest


DRAIN_TRIGGER_EVENTS = {"spot_interruption", "capacity_rebalance"}


def is_drain_trigger(event: InstanceEvent) -> bool:
    return event.event_type in DRAIN_TRIGGER_EVENTS


def is_final_interruption(event: InstanceEvent) -> bool:
    return event.event_type == "spot_interruption"


def audit(action: str, event: InstanceEvent, replacement_capacity_added: int, reason: str) -> dict[str, object]:
    return DrainDecision(
        action=action,
        event_id=event.event_id,
        instance_id=event.instance_id,
        event_type=event.event_type,
        replacement_capacity_added=replacement_capacity_added,
        reason=reason,
    ).as_audit()


def replace_instance(
    instances: tuple[ContainerInstance, ...],
    replacement: ContainerInstance,
) -> tuple[ContainerInstance, ...]:
    return tuple(replacement if instance.instance_id == replacement.instance_id else instance for instance in instances)


def drain_instance(instance: ContainerInstance) -> ContainerInstance:
    return instance.as_draining()


def replacement_capacity_for(instance: ContainerInstance) -> int:
    return instance.drainable_task_count()


def sorted_events(events: list[InstanceEvent]) -> list[InstanceEvent]:
    return sorted(events, key=lambda event: (event.minute, event.event_id))


def placement_targets(cluster: ClusterState, request: PlacementRequest) -> list[str]:
    targets: list[str] = []
    for instance in cluster.instances:
        if instance.capacity_provider != request.capacity_provider:
            continue
        if instance.state != "ACTIVE":
            continue
        if not instance.accepting_placements:
            continue
        targets.append(instance.instance_id)
    return targets


class DrainAccumulator:
    def __init__(self) -> None:
        self.audit_events: list[dict[str, object]] = []

    def ignored_unknown(self, event: InstanceEvent) -> None:
        self.audit_events.append(audit("ignored_unknown_instance", event, 0, "instance_not_found"))

    def ignored_event(self, event: InstanceEvent) -> None:
        self.audit_events.append(audit("ignored_event", event, 0, "event_does_not_trigger_drain"))

    def already_draining(self, event: InstanceEvent) -> None:
        self.audit_events.append(audit("already_draining", event, 0, "instance_already_draining"))

    def drain_started(self, event: InstanceEvent, replacement_capacity_added: int) -> None:
        self.audit_events.append(
            audit("drain_started", event, replacement_capacity_added, "drain_triggered")
        )


class ClusterDrainState:
    def __init__(self, cluster: ClusterState) -> None:
        self.cluster = cluster
        self.accumulator = DrainAccumulator()

    def instance(self, instance_id: str) -> ContainerInstance | None:
        return self.cluster.get_instance(instance_id)

    def start_drain(self, event: InstanceEvent, instance: ContainerInstance) -> None:
        replacement_capacity_added = replacement_capacity_for(instance)
        self.cluster = ClusterState(
            instances=replace_instance(self.cluster.instances, drain_instance(instance)),
            desired_replacement_capacity=self.cluster.desired_replacement_capacity + replacement_capacity_added,
            cluster_name=self.cluster.cluster_name,
        )
        self.accumulator.drain_started(event, replacement_capacity_added)

    def result(self) -> tuple[ClusterState, list[dict[str, object]]]:
        return self.cluster, self.accumulator.audit_events

    def placement_targets(self, request: PlacementRequest) -> list[str]:
        return placement_targets(self.cluster, request)

