from __future__ import annotations

from drain_state import ClusterDrainState, audit, drain_instance, is_final_interruption, placement_targets, replace_instance, sorted_events
from ecs_models import ClusterState, ContainerInstance, InstanceEvent, PlacementRequest


def _replace_instance(instances: tuple[ContainerInstance, ...], replacement: ContainerInstance) -> tuple[ContainerInstance, ...]:
    return replace_instance(instances, replacement)


def _drained_instance(instance: ContainerInstance) -> ContainerInstance:
    return drain_instance(instance)


def _audit(action: str, event: InstanceEvent, replacement_capacity_added: int) -> dict[str, object]:
    reason = {
        "ignored_unknown_instance": "instance_not_found",
        "ignored_event": "event_does_not_trigger_drain",
        "already_draining": "instance_already_draining",
        "drain_started": "drain_triggered",
    }.get(action, "planner_event")
    return audit(action, event, replacement_capacity_added, reason)


def _start_drain(current: ClusterState, event: InstanceEvent, instance: ContainerInstance) -> tuple[ClusterState, dict[str, object]]:
    replacement_capacity_added = instance.running_tasks
    updated = ClusterState(
        instances=_replace_instance(current.instances, _drained_instance(instance)),
        desired_replacement_capacity=current.desired_replacement_capacity + replacement_capacity_added,
        cluster_name=current.cluster_name,
    )
    return updated, _audit("drain_started", event, replacement_capacity_added)


def plan_spot_drain(
    cluster: ClusterState,
    events: list[InstanceEvent],
) -> dict[str, object]:
    current = cluster
    audit_events: list[dict[str, object]] = []

    for event in sorted_events(events):
        instance = current.get_instance(event.instance_id)
        if instance is None:
            audit_events.append(_audit("ignored_unknown_instance", event, 0))
            continue
        if not is_final_interruption(event):
            audit_events.append(_audit("ignored_event", event, 0))
            continue
        if instance.state == "DRAINING":
            audit_events.append(_audit("already_draining", event, 0))
            continue

        current, audit_event = _start_drain(current, event, instance)
        audit_events.append(audit_event)

    return summarize_drain_plan(current, audit_events)


def summarize_drain_plan(
    cluster: ClusterState,
    audit_events: list[dict[str, object]],
) -> dict[str, object]:
    draining_instances = [instance for instance in cluster.instances if instance.state == "DRAINING"]
    active_instances = [instance for instance in cluster.instances if instance.state == "ACTIVE"]
    placement_request = PlacementRequest(task_count=1)
    return {
        "draining_instance_ids": [instance.instance_id for instance in draining_instances],
        "active_instance_ids": [instance.instance_id for instance in active_instances],
        "desired_replacement_capacity": cluster.desired_replacement_capacity,
        "new_placements_blocked_on": [instance.instance_id for instance in draining_instances],
        "audit_events": audit_events,
        "audit_event_count": len(audit_events),
        "placement_target_ids": placement_targets(cluster, placement_request),
    }


class EcsSpotDrainPlanner:
    def __init__(self, cluster: ClusterState) -> None:
        self.cluster = cluster

    def plan(self, events: list[InstanceEvent]) -> dict[str, object]:
        result = plan_spot_drain(self.cluster, events)
        self.cluster = ClusterState(
            instances=tuple(
                ContainerInstance(
                    instance_id=instance.instance_id,
                    capacity_provider=instance.capacity_provider,
                    state="DRAINING" if instance.instance_id in result["draining_instance_ids"] else instance.state,
                    running_tasks=instance.running_tasks,
                    az=instance.az,
                    accepting_placements=instance.instance_id not in result["draining_instance_ids"],
                    protected_tasks=instance.protected_tasks,
                )
                for instance in self.cluster.instances
            ),
            desired_replacement_capacity=int(result["desired_replacement_capacity"]),
            cluster_name=self.cluster.cluster_name,
        )
        return result

    def snapshot(self) -> dict[str, object]:
        return summarize_drain_plan(self.cluster, [])


def plan_with_state(cluster: ClusterState, events: list[InstanceEvent]) -> dict[str, object]:
    state = ClusterDrainState(cluster)
    for event in sorted_events(events):
        instance = state.instance(event.instance_id)
        if instance is None:
            state.accumulator.ignored_unknown(event)
            continue
        if not is_final_interruption(event):
            state.accumulator.ignored_event(event)
            continue
        if instance.state == "DRAINING":
            state.accumulator.already_draining(event)
            continue
        state.start_drain(event, instance)
    updated, audit_events = state.result()
    return summarize_drain_plan(updated, audit_events)

