        self.cluster = cluster

    def plan(self, events: list[InstanceEvent]) -> dict[str, object]:
        result = plan_spot_drain(self.cluster, events)
        self.cluster = ClusterState(
            instances=tuple(
                ContainerInstance(
                    instance_id=instance.instance_id,
                    capacity_provider=instance.capacity_provider,
                    state="DRAINING" if instance.instance_id in result["draining_instance_ids"] else instance.state,
                    running_tasks=instance.running_tasks,
                    az=instance.az,
                    accepting_placements=instance.instance_id not in result["draining_instance_ids"],
                    protected_tasks=instance.protected_tasks,
                )
                for instance in self.cluster.instances
            ),
            desired_replacement_capacity=int(result["desired_replacement_capacity"]),
            cluster_name=self.cluster.cluster_name,
        )
        return result

    def snapshot(self) -> dict[str, object]:
        return summarize_drain_plan(self.cluster, [])


def plan_with_state(cluster: ClusterState, events: list[InstanceEvent]) -> dict[str, object]:
    state = ClusterDrainState(cluster)
    for event in sorted_events(events):
        instance = state.instance(event.instance_id)
        if instance is None:
            state.accumulator.ignored_unknown(event)
            continue
        if not is_final_interruption(event):
            state.accumulator.ignored_event(event)
            continue
        if instance.state == "DRAINING":
            state.accumulator.already_draining(event)
            continue
        state.start_drain(event, instance)
    updated, audit_events = state.result()
    return summarize_drain_plan(updated, audit_events)
